import os, time, random, hashlib
from cryptography.hazmat.primitives import hashes
sizes=[1024, 10240, 102400, 1048576, 10485760]  # 1K to 10MB
for size in sizes:
    plaintext=os.urandom(size)
    t0=time.time();
    ctx=hashes.Hash(hashes.SHA256());ctx.update(plaintext);ctx.finalize();
    t1=time.time();
    c_time=t1-t0
    t0=time.time();
    hashlib.sha256(plaintext).digest();
